/* Language preference is independent of catalogue content and routing. */
(()=>{'use strict';
const base=new URL('.',document.currentScript.src),key='biblioteca-language';let language='en',dictionary={},busy=false;
const originals=new WeakMap(),attrs=new WeakMap();
const biographyShards=new Map();
function biographyShard(text){let hash=2166136261;for(let i=0;i<text.length;i++)hash=Math.imul(hash^text.charCodeAt(i),16777619)>>>0;return (hash&255).toString(16).padStart(2,'0');}
function requestBiography(text){const key=biographyShard(text);if(biographyShards.has(key))return;const entry={state:'loading'};biographyShards.set(key,entry);entry.promise=fetch(new URL('biographies-it/'+key+'.json',base)).then(response=>{if(!response.ok)throw Error('Biography translation unavailable');return response.json();}).then(data=>{for(const [source,translation] of Object.entries(data))if(!(source in dictionary))dictionary[source]=translation;entry.state='ready';apply();}).catch(()=>{entry.state='error';apply();});}
const biographySelector='.author-panel-biography>p:not(.author-panel-source):not(.biography-context-label):not(.biography-translation-note),.reading-author-bio:not(.reading-author-bio-empty),.author-alternatives-track article>p,.person-tile .author-card-bio,.author-profile .bio,.author-hero .bio,.identity-candidate .bio';

const storyCopies={
 '#contextIntro h1':'Stai per esplorare una biblioteca di famiglia,<br>raccontata attraverso il suo catalogo.',
 '#labourTitle':'Per battere a macchina ogni scheda,<br>impiegò…',
 '#manyTitle':'49.780 schede.<br><em>Una dopo l’altra.</em>',
 '#timeTitle':'La collezione attraversa i secoli,<br>dal <em>Quattrocento</em><br>al <em>Novecento.</em>'
};const storyOriginals=new Map();

const excluded=node=>node.parentElement?.closest('script,style,code,textarea,.intro-word,#typedNarrative,#untypedNarrative,.generated-book-cover,.card-search-result strong,.card-search-result>span,.author-panel-work strong,.detail-heading h2,#detailAuthor,.author-title-card h2,.author-neighbour strong,.reading-author-body h3,.person-tile h3,.book-tile h3,.hover-card strong,.language-switch');
function translate(s){const trim=s.trim();if(/^The catalogue links \d+ records? to the heading /.test(trim)){return trim.replace(/^The catalogue links (\d+) records? to the heading /,'Il catalogo collega $1 schede al nome ').replace('Transcribed publication dates range from ','Le date di pubblicazione trascritte vanno dal ').replace(/(Le date di pubblicazione trascritte vanno dal [^ ]+) to /,'$1 al ').replace('Transcribed publication date: ','Data di pubblicazione trascritta: ').replace('Linked titles include ','Tra i titoli collegati figurano ').replace('A linked title is ','Un titolo collegato è ').replace('These cards do not yet establish a verified personal biography.','Queste schede non consentono ancora di stabilire una biografia personale verificata.');}if(dictionary[trim])return s.replace(trim,dictionary[trim]);let m;if((m=trim.match(/^(.*) — Wikipedia contributors( ↗)?$/)))return m[1]+' — autori di Wikipedia'+(m[2]||'');if((m=trim.match(/^(Revision history and contributors|CC BY-SA 4.0 — shortened excerpt)( ↗)$/)))return dictionary[m[1]]+m[2];if((m=trim.match(/^Confidence score (\d+) out of 100$/)))return `Punteggio di attendibilità ${m[1]} su 100`;if((m=trim.match(/^Confidence score · (higher|moderate|low) support\. Editorial scale, not a probability\.$/)))return 'Punteggio di attendibilità · '+({higher:'maggiore',moderate:'moderato',low:'limitato'}[m[1]])+' supporto. Scala editoriale, non una probabilità.';if((m=trim.match(/^([\d,.]+) of ([\d,.]+) cards$/)))return `${m[1]} di ${m[2]} schede`;if((m=trim.match(/^([\d,.]+) connected cards$/)))return `${m[1]} schede collegate`;if((m=trim.match(/^Possible identification: (.*)$/)))return 'Possibile identificazione: '+m[1];if((m=trim.match(/^Possible identity: (.*)$/)))return 'Possibile identità: '+m[1];return s;}
function apply(){if(busy||!document.body)return;busy=true;observer.disconnect();const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(excluded(n))continue;const last=originals.get(n);let original=last&&n.nodeValue===last.rendered?last.original:n.nodeValue;const isBiography=!!n.parentElement?.closest(biographySelector)&&original.trim().length>60;
if(language==='it'&&isBiography&&!dictionary[original.trim()])requestBiography(original.trim());
const rendered=language==='it'?translate(original):original;if(n.nodeValue!==rendered)n.nodeValue=rendered;originals.set(n,{original,rendered});}
for(const node of document.querySelectorAll('[placeholder],[aria-label],[title]')){if(node.closest('.language-switch'))continue;let saved=attrs.get(node)||{};for(const attr of ['placeholder','aria-label','title']){if(!node.hasAttribute(attr))continue;const value=node.getAttribute(attr),last=saved[attr],original=last&&value===last.rendered?last.original:value,rendered=language==='it'?translate(original):original;if(value!==rendered)node.setAttribute(attr,rendered);saved[attr]={original,rendered};}attrs.set(node,saved);}
for(const [selector,italian] of Object.entries(storyCopies)){const node=document.querySelector(selector);if(!node)continue;if(!storyOriginals.has(selector))storyOriginals.set(selector,node.innerHTML);const html=language==='it'?italian:storyOriginals.get(selector);if(node.innerHTML!==html)node.innerHTML=html;}
const intro=document.querySelectorAll('.intro-word');const words=language==='it'?['Per','gran','parte','del','secolo','scorso,','mio','nonno,','Roberto','Piontelli,','uno','scienziato,','raccolse','migliaia','di','libri.']:['For','the','better','part','of','the','last','century,','my','grandfather,','Roberto','Piontelli,','a','scientist,','collected','thousands','of','books.'];intro.forEach((node,i)=>{const text=words[i]||'';if(node.textContent!==text)node.textContent=text;});
for(const block of document.querySelectorAll('.author-panel-biography,.reading-author-body,.author-alternatives-track article,.author-profile,.author-hero')){
 const paragraphs=[...block.querySelectorAll('p')].filter(p=>p.matches(biographySelector));
 const translated=paragraphs.some(p=>[...p.childNodes].some(n=>originals.has(n)&&originals.get(n).original!==n.nodeValue));
 let note=block.querySelector('.biography-translation-note');
 if(language==='it'&&translated){if(!note){note=document.createElement('p');note.className='biography-translation-note';note.textContent='Traduzione automatica dall’inglese. Il testo originale e le fonti sono disponibili selezionando EN.';block.append(note);}}else note?.remove();
}
document.documentElement.lang=language;document.querySelectorAll('.language-switch button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===language)));observer.observe(document.body,{subtree:true,childList:true,characterData:true});busy=false;}
const observer=new MutationObserver(()=>apply());
function set(lang,save=false){language=lang==='it'?'it':'en';if(save)try{localStorage.setItem(key,language)}catch{}apply();window.dispatchEvent(new CustomEvent('biblioteca-language',{detail:language}));}
async function init(){dictionary=await fetch(new URL('translations-it.json',base)).then(r=>r.json());const switcher=document.createElement('div');switcher.className='language-switch';switcher.setAttribute('role','group');switcher.setAttribute('aria-label','Language / Lingua');for(const [code,label] of [['en','EN'],['it','IT']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.lang=code;b.lang=code;b.setAttribute('aria-label',code==='it'?'Italiano':'English');b.onclick=()=>set(code,true);switcher.append(b);}document.body.append(switcher);
let saved;try{saved=localStorage.getItem(key)}catch{}set(saved||((navigator.language||'').startsWith('it')?'it':'en'));if(saved)return;
try{const response=await fetch('https://ipapi.co/country/',{signal:AbortSignal.timeout(2500),credentials:'omit',referrerPolicy:'no-referrer'});const country=(await response.text()).trim();let manual;try{manual=localStorage.getItem(key)}catch{}if(response.ok&&/^[A-Z]{2}$/.test(country)&&!manual)set(country==='IT'?'it':'en');}catch{/* Browser language remains the fallback. */}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>init().catch(console.warn));else init().catch(console.warn);
})();
